(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.012+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(x*0.035-t*0.5)*6 + Math.cos(y*0.04+t*0.45)*5;
  const w2y = Math.cos(y*0.033+t*0.48)*6 + Math.sin(x*0.038-t*0.42)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.4)*90, 60+Math.cos(t*0.35)*40, 0.075, 2.1, 1.0],
    [360+Math.cos(t*0.45)*90, 60+Math.sin(t*0.5)*40, 0.085, 1.8, 0.9],
    [80+Math.cos(t*0.55)*70, 180+Math.sin(t*0.4)*50, 0.065, 2.4, 1.1],
    [400+Math.sin(t*0.38)*80, 170+Math.cos(t*0.48)*55, 0.095, 1.6, 0.85],
    [240+Math.sin(t*0.3+2)*130, 120+Math.cos(t*0.45+1)*80, 0.055, 2.6, 1.2],
    [180+Math.cos(t*0.6+1)*60, 100+Math.sin(t*0.7+3)*70, 0.11, 1.4, 0.8],
    [300+Math.sin(t*0.42+4)*75, 140+Math.cos(t*0.55+2)*65, 0.07, 2.2, 1.05],
    [240+Math.cos(t*0.33+5)*110, 200+Math.sin(t*0.52)*60, 0.08, 2.0, 0.95],
    [160+Math.sin(t*0.5+3)*50, 30+Math.cos(t*0.65)*35, 0.1, 1.7, 0.9],
    [320+Math.cos(t*0.37+2)*55, 210+Math.sin(t*0.43+1)*40, 0.09, 1.9, 1.0]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    mS += Math.sin(d*f*1.4-t*sp*0.8+3.0)*w*0.4;
  }
  const act=aS/8.5, inh=iS/8.5, mod=mS/8.5;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2 = (Math.sin(sx*0.06+sy*0.04-t*1.3)+Math.cos(sx*0.045-sy*0.055+t*0.9))/2;
  const micro = (Math.sin(sx*0.12+t*2.5)*Math.cos(sy*0.11-t*2.2)+Math.sin((sx-sy)*0.08+t*1.8)*0.5)*0.3;
  const bg = bg1*0.5+bg2*0.3+micro;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.4), sp2=Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.4;
  const spiral=(sp1+sp2)*0.35+sp3;
  const radPulse = Math.sin(dist*0.03-t*1.8)*0.3*Math.exp(-dist*0.003);
  const cellA = Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB = Math.sin((sx+sy)*0.09+t*0.6)*Math.sin((sx-sy)*0.08-t*0.4);
  const cell = Math.tanh((cellA+cellB*0.7)*1.8)*0.25;
  const caustic = Math.pow(Math.max(0, Math.sin(act*3.5+inh*2)*0.5+0.5), 3)*0.4;
  const r1 = act - inh*0.65 + bg*0.25 + spiral*0.4 + mod*0.3;
  const r2 = act*0.5 + inh*0.8 - bg*0.15 + spiral*0.2 + radPulse;
  const cross = Math.tanh(r1*2.0)*Math.tanh(r2*1.5)*0.7 + Math.tanh(r1*1.2)*0.3;
  const blend = cross*0.7 + cell*0.15 + caustic*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[10,35,95],[12,65,120],[18,105,135],
    [35,155,145],[120,190,130],[200,195,80],
    [225,155,65],[215,100,75],[180,60,80],
    [130,35,85],[65,18,65],[30,12,58],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm = f*f*(3-2*f);
  const energy = Math.abs(cross);
  const lum = 0.82+energy*0.18;
  const edge = energy>0.65?1.0+energy*0.18:1.0;
  const shimmer = 1.0+Math.sin(ang*5+dist*0.08+t*3)*0.04*energy;
  const bright = lum*edge*shimmer;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*bright)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*bright)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*bright)|0
  ];
}
